<?php require_once __DIR__.'/db.php'; $products=$pdo->query("SELECT id,name,selling_price FROM products WHERE status='Active' ORDER BY name")->fetchAll(); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Place an order | GlassMart</title><link rel="stylesheet" href="style.css"></head><body class="auth-page"><main class="auth-card order-card"><div class="brand auth-brand"><span class="brand-mark">G</span><div><strong>GLASSMART</strong><small>Online orders</small></div></div><h1>Place an order</h1><p class="auth-subtitle">Send your order request to GlassMart.</p><div id="order-message"></div><form id="public-order-form" class="auth-form"><label>Your full name<input name="customer" required></label><label>Phone number<input name="phone" required placeholder="07xx xxx xxx"></label><label>Product<select name="product_id" required><option value="">Choose a product</option><?php foreach($products as $p): ?><option value="<?= (int)$p['id'] ?>"><?= htmlspecialchars($p['name']) ?> — KSh <?= number_format((float)$p['selling_price'],2) ?></option><?php endforeach; ?></select></label><label>Quantity<input name="quantity" type="number" min="1" value="1" required></label><label>Delivery location / instructions<textarea name="notes" rows="3"></textarea></label><button class="primary" type="submit">Submit order</button></form><p class="auth-foot"><a href="login.php">Staff and management sign in</a></p></main><script>
document.getElementById('public-order-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,d=Object.fromEntries(new FormData(f));const box=document.getElementById('order-message');try{const r=await fetch('api.php?action=public_order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});const j=await r.json();if(!r.ok)throw new Error(j.error||'Order failed');box.className='form-success';box.textContent=j.message;f.reset();}catch(err){box.className='form-error';box.textContent=err.message;}});
</script></body></html>
